// MARK: - Outputs

/// What kind of output a wire type is.
public enum OutputKind: String, Sendable {
    case state, event, request
}

/// A session output decoded by its wire type name (`onEvent(type_name, json)`).
public enum SessionOutput: Sendable, Equatable {
    case capoAdviceState(CapoAdviceState)
    case chordSheetState(ChordSheetState)
    case documentState(DocumentState)
    case editorState(EditorState)
    case highlightState(HighlightState)
    case identifierState(IdentifierState)
    case instrumentMenuState(InstrumentMenuState)
    case playbackState(PlaybackState)
    case recentDocumentsState(RecentDocumentsState)
    case settingsState(SettingsState)
    case songDefaultsState(SongDefaultsState)
    case startupState(StartupState)
    case statusState(StatusState)
    case toolbarState(ToolbarState)
    case voicingEditorState(VoicingEditorState)
    case voicingMenuState(VoicingMenuState)
    case audioUnavailable(AudioUnavailable)
    case closeApproved(CloseApproved)
    case directiveCheck(DirectiveCheck)
    case directiveHint(DirectiveHint)
    case editRefused(EditRefused)
    case quickStartContent(QuickStartContent)
    case renameFailed(RenameFailed)
    case textEdited(TextEdited)
    case unexpectedError(UnexpectedError)
    case userError(UserError)
    case voicingEditorSchema(VoicingEditorSchema)
    case confirmDiscardRequest(ConfirmDiscardRequest)
    case insertDirectiveRequest(InsertDirectiveRequest)
    case paintPdfRequest(PaintPdfRequest)
    case pickDocumentRequest(PickDocumentRequest)

    /// The wire type name (the Python class name).
    public var typeName: String {
        switch self {
        case .capoAdviceState: return "CapoAdviceState"
        case .chordSheetState: return "ChordSheetState"
        case .documentState: return "DocumentState"
        case .editorState: return "EditorState"
        case .highlightState: return "HighlightState"
        case .identifierState: return "IdentifierState"
        case .instrumentMenuState: return "InstrumentMenuState"
        case .playbackState: return "PlaybackState"
        case .recentDocumentsState: return "RecentDocumentsState"
        case .settingsState: return "SettingsState"
        case .songDefaultsState: return "SongDefaultsState"
        case .startupState: return "StartupState"
        case .statusState: return "StatusState"
        case .toolbarState: return "ToolbarState"
        case .voicingEditorState: return "VoicingEditorState"
        case .voicingMenuState: return "VoicingMenuState"
        case .audioUnavailable: return "AudioUnavailable"
        case .closeApproved: return "CloseApproved"
        case .directiveCheck: return "DirectiveCheck"
        case .directiveHint: return "DirectiveHint"
        case .editRefused: return "EditRefused"
        case .quickStartContent: return "QuickStartContent"
        case .renameFailed: return "RenameFailed"
        case .textEdited: return "TextEdited"
        case .unexpectedError: return "UnexpectedError"
        case .userError: return "UserError"
        case .voicingEditorSchema: return "VoicingEditorSchema"
        case .confirmDiscardRequest: return "ConfirmDiscardRequest"
        case .insertDirectiveRequest: return "InsertDirectiveRequest"
        case .paintPdfRequest: return "PaintPdfRequest"
        case .pickDocumentRequest: return "PickDocumentRequest"
        }
    }

    public var kind: OutputKind {
        switch self {
        case .capoAdviceState: return .state
        case .chordSheetState: return .state
        case .documentState: return .state
        case .editorState: return .state
        case .highlightState: return .state
        case .identifierState: return .state
        case .instrumentMenuState: return .state
        case .playbackState: return .state
        case .recentDocumentsState: return .state
        case .settingsState: return .state
        case .songDefaultsState: return .state
        case .startupState: return .state
        case .statusState: return .state
        case .toolbarState: return .state
        case .voicingEditorState: return .state
        case .voicingMenuState: return .state
        case .audioUnavailable: return .event
        case .closeApproved: return .event
        case .directiveCheck: return .event
        case .directiveHint: return .event
        case .editRefused: return .event
        case .quickStartContent: return .event
        case .renameFailed: return .event
        case .textEdited: return .event
        case .unexpectedError: return .event
        case .userError: return .event
        case .voicingEditorSchema: return .event
        case .confirmDiscardRequest: return .request
        case .insertDirectiveRequest: return .request
        case .paintPdfRequest: return .request
        case .pickDocumentRequest: return .request
        }
    }

    /// Decode one output.
    ///
    /// - Throws: ``BridgeDecodeError`` for an unknown type name or a payload
    ///   that doesn't match the type (unknown keys are ignored).
    public static func decode(typeName: String, json: String) throws -> SessionOutput {
        let data = Data(json.utf8)
        do {
            switch typeName {
            case "CapoAdviceState": return .capoAdviceState(try BridgeJSON.decoder.decode(CapoAdviceState.self, from: data))
            case "ChordSheetState": return .chordSheetState(try BridgeJSON.decoder.decode(ChordSheetState.self, from: data))
            case "DocumentState": return .documentState(try BridgeJSON.decoder.decode(DocumentState.self, from: data))
            case "EditorState": return .editorState(try BridgeJSON.decoder.decode(EditorState.self, from: data))
            case "HighlightState": return .highlightState(try BridgeJSON.decoder.decode(HighlightState.self, from: data))
            case "IdentifierState": return .identifierState(try BridgeJSON.decoder.decode(IdentifierState.self, from: data))
            case "InstrumentMenuState": return .instrumentMenuState(try BridgeJSON.decoder.decode(InstrumentMenuState.self, from: data))
            case "PlaybackState": return .playbackState(try BridgeJSON.decoder.decode(PlaybackState.self, from: data))
            case "RecentDocumentsState": return .recentDocumentsState(try BridgeJSON.decoder.decode(RecentDocumentsState.self, from: data))
            case "SettingsState": return .settingsState(try BridgeJSON.decoder.decode(SettingsState.self, from: data))
            case "SongDefaultsState": return .songDefaultsState(try BridgeJSON.decoder.decode(SongDefaultsState.self, from: data))
            case "StartupState": return .startupState(try BridgeJSON.decoder.decode(StartupState.self, from: data))
            case "StatusState": return .statusState(try BridgeJSON.decoder.decode(StatusState.self, from: data))
            case "ToolbarState": return .toolbarState(try BridgeJSON.decoder.decode(ToolbarState.self, from: data))
            case "VoicingEditorState": return .voicingEditorState(try BridgeJSON.decoder.decode(VoicingEditorState.self, from: data))
            case "VoicingMenuState": return .voicingMenuState(try BridgeJSON.decoder.decode(VoicingMenuState.self, from: data))
            case "AudioUnavailable": return .audioUnavailable(try BridgeJSON.decoder.decode(AudioUnavailable.self, from: data))
            case "CloseApproved": return .closeApproved(try BridgeJSON.decoder.decode(CloseApproved.self, from: data))
            case "DirectiveCheck": return .directiveCheck(try BridgeJSON.decoder.decode(DirectiveCheck.self, from: data))
            case "DirectiveHint": return .directiveHint(try BridgeJSON.decoder.decode(DirectiveHint.self, from: data))
            case "EditRefused": return .editRefused(try BridgeJSON.decoder.decode(EditRefused.self, from: data))
            case "QuickStartContent": return .quickStartContent(try BridgeJSON.decoder.decode(QuickStartContent.self, from: data))
            case "RenameFailed": return .renameFailed(try BridgeJSON.decoder.decode(RenameFailed.self, from: data))
            case "TextEdited": return .textEdited(try BridgeJSON.decoder.decode(TextEdited.self, from: data))
            case "UnexpectedError": return .unexpectedError(try BridgeJSON.decoder.decode(UnexpectedError.self, from: data))
            case "UserError": return .userError(try BridgeJSON.decoder.decode(UserError.self, from: data))
            case "VoicingEditorSchema": return .voicingEditorSchema(try BridgeJSON.decoder.decode(VoicingEditorSchema.self, from: data))
            case "ConfirmDiscardRequest": return .confirmDiscardRequest(try BridgeJSON.decoder.decode(ConfirmDiscardRequest.self, from: data))
            case "InsertDirectiveRequest": return .insertDirectiveRequest(try BridgeJSON.decoder.decode(InsertDirectiveRequest.self, from: data))
            case "PaintPdfRequest": return .paintPdfRequest(try BridgeJSON.decoder.decode(PaintPdfRequest.self, from: data))
            case "PickDocumentRequest": return .pickDocumentRequest(try BridgeJSON.decoder.decode(PickDocumentRequest.self, from: data))
            default: throw BridgeDecodeError.unknownType(typeName)
            }
        } catch let error as BridgeDecodeError {
            throw error
        } catch {
            throw BridgeDecodeError.badPayload(typeName, String(describing: error))
        }
    }
}

